export const CASTLE_UNLOCKS={wood:0,foundation:0,beam:0,stairs:0,platform:0,battlement:0,barricade:0,trap:0,footman:0,flag:0,stone:5,gate:5,roof:5,window:5,arch:8,archer:12,tower:12,bridge:18,cannon:25,barrier:30,reinforced:40,repair:50,ballista:60,decor:70,catapult:85,rune:120};
