 initializeItem(b){b.owner??=this.ownerId||'local';b.uid??=this.allocateId();b.level??=1;b.home={x:b.x,y:b.y};b.maxHP=this.spec(b).hp;b.hp??=b.maxHP;return b;}
 inspect(x,y){if(Math.abs(x-this.king.x)<28&&y>480){this.selected=this.king;this.inspecting=true;return true;}const b=[...this.items].reverse().find(b=>b.hp!==0&&Math.abs(x-b.x)<this.box(b).w/2+10&&Math.abs(y-b.y)<this.box(b).h/2+12);if(b){this.selected=b;this.inspecting=true;return true;}return false;}
 upgrade(b=this.selected){if(!b||b!==this.king&&!this.items.includes(b)||b.hp<=0)return false;const p=this.spec(b);if(this.phase!=='build'){this.feedback='Upgrade during construction between assaults.';return false;}if(!p.upgradeCost){this.feedback='Elite level reached.';return false;}if(this.spent+p.upgradeCost>this.budget){this.feedback='Not enough gold for this upgrade.';return false;}if(b===this.king)this.history=new History(this);else this.history.push();b.level=p.level+1;const next=this.spec(b),missing=p.hp-(b===this.king?this.coreHP:b.hp??p.hp);if(b===this.king){this.coreHP=Math.max(1,next.hp-missing);this.maxCore=next.hp;}else{b.maxHP=next.hp;b.hp=Math.max(1,next.hp-missing);}this.feedback=p.name+' upgraded to '+next.tier+' · Level '+next.level+'.';this.events.push('upgrade');return true;}
